select jsonb_build_object('users',(select count(*)from auth.users where id::text like 'fd340000-0000-4000-8000-%'),'companies',(select count(*)from public.companies where id::text like 'fd340000-0000-4000-8000-%'),'customers',(select count(*)from public.customers where id::text like 'fd340000-0000-4000-8000-%'),'vehicles',(select count(*)from public.vehicles where id::text like 'fd340000-0000-4000-8000-%'),'stock',(select count(*)from public.stock_items where id::text like 'fd340000-0000-4000-8000-%'),'deals',(select count(*)from public.deals where id::text like 'fd340000-0000-4000-8000-%'),'offers',(select count(*)from public.offers where id::text like 'fd340000-0000-4000-8000-%'),'documents',(select count(*)from public.documents where id::text like 'fd340000-0000-4000-8000-%'),'archives',(select count(*)from public.offer_document_archives where company_id::text like 'fd340000-0000-4000-8000-%'));
